{
  "requirements": [
    {
      "id": "F-01",
      "text": "The system shall ensure compliance with applicable financial regulations and standards to guarantee legal accountability.",
      "quality_axes": ["Responsibility"],
      "derived_from": ["RES-01"],
      "kaos_level": "strategic",
      "parent": null
    },
    {
      "id": "F-02",
      "text": "The system shall implement a comprehensive user access control framework to restrict modifications to authorized personnel.",
      "quality_axes": ["Trustworthiness|Responsibility"],
      "derived_from": ["RES-02", "TRU-02"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-03",
      "text": "The system shall maintain a unified audit trail of all transactions to ensure accountability and transparency.",
      "quality_axes": ["Safety|Trustworthiness"],
      "derived_from": ["SAF-03", "TRU-03"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-04",
      "text": "The system shall ensure that all financial transactions are recorded accurately to prevent data loss or corruption.",
      "quality_axes": ["Safety"],
      "derived_from": ["SAF-01"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-05",
      "text": "The system shall implement error handling mechanisms to manage and recover from faults during transaction processing.",
      "quality_axes": ["Safety"],
      "derived_from": ["SAF-04"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-06",
      "text": "The system shall support safe degradation, ensuring that users can access essential functionalities even during outages.",
      "quality_axes": ["Safety"],
      "derived_from": ["SAF-05"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-07",
      "text": "The system shall validate currency conversions to ensure accuracy and prevent financial discrepancies.",
      "quality_axes": ["Safety|Efficiency"],
      "derived_from": ["SAF-06", "EFF-06"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-08",
      "text": "The system shall ensure rapid processing of financial transactions within 2 seconds to optimize responsiveness.",
      "quality_axes": ["Efficiency"],
      "derived_from": ["EFF-01"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-09",
      "text": "The system shall support concurrent processing of at least 100 users to ensure adequate throughput.",
      "quality_axes": ["Efficiency"],
      "derived_from": ["EFF-02"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-10",
      "text": "The system shall utilize efficient data structures to minimize memory usage by 30% compared to traditional methods.",
      "quality_axes": ["Efficiency"],
      "derived_from": ["EFF-03"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-11",
      "text": "The system shall generate financial reports in under 5 seconds for datasets up to 10,000 transactions.",
      "quality_axes": ["Efficiency"],
      "derived_from": ["EFF-04"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-12",
      "text": "The system shall implement caching for frequently accessed data to reduce latency by at least 50%.",
      "quality_axes": ["Efficiency"],
      "derived_from": ["EFF-05"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-13",
      "text": "The system shall provide functionalities to detect and alert users about potential financial discrepancies or fraud.",
      "quality_axes": ["Responsibility"],
      "derived_from": ["RES-04"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-14",
      "text": "The system shall provide multi-currency support with transparent exchange rates to ensure fairness in international transactions.",
      "quality_axes": ["Responsibility"],
      "derived_from": ["RES-07"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-15",
      "text": "The system shall ensure that all financial transactions are encrypted during transmission and storage.",
      "quality_axes": ["Trustworthiness"],
      "derived_from": ["TRU-01"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-16",
      "text": "The system shall validate data input to prevent unauthorized or malicious data entry.",
      "quality_axes": ["Trustworthiness"],
      "derived_from": ["TRU-04"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-17",
      "text": "The system shall support two-factor authentication for all users accessing financial data.",
      "quality_axes": ["Trustworthiness"],
      "derived_from": ["TRU-05"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-18",
      "text": "The system shall log all user access and modifications to data, retaining logs for review.",
      "quality_axes": ["Trustworthiness"],
      "derived_from": ["TRU-06"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-19",
      "text": "The system shall provide users with sustainability reports showing energy and resource consumption metrics.",
      "quality_axes": ["Sustainability"],
      "derived_from": ["GRN-05"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-20",
      "text": "The system shall minimize energy consumption during data processing by using efficient algorithms and data structures.",
      "quality_axes": ["Sustainability"],
      "derived_from": ["GRN-01"],
      "kaos_level": "operational",
      "parent": null
    }
  ],
